import collections, hashlib, json, os, re
from pathlib import Path
W=Path(os.environ.get('WORKSPACES',Path.home()/'orca/workspaces'))
M=W/'westlake-harness'; O=Path(__file__).resolve().parent
D=W/'westlake-inputs/reports/2026-10-08-harness-briefing/briefing.zh.md'
capture=json.loads((O/'evidence/reviewed-source-lines.json').read_text())
lines=[capture['lines'].get(str(i),'') for i in range(1,capture['original_line_count']+1)]; findings=[]
def cite(p,needle=None):
 t=(M/p).read_text(errors='replace').splitlines() if (M/p).is_file() else (O/p).read_text(errors='replace').splitlines()
 if needle is None:return f'{p}:1'
 hits=[i for i,l in enumerate(t,1) if needle in l]
 if not hits:raise ValueError((p,needle))
 return f'{p}:{hits[0]}'
def add(n,verdict,reason,fix,refs,claim=None):
 findings.append(dict(id=f'F{len(findings)+1:03}',draft_line=n,original_sentence=lines[n-1],claim=claim or lines[n-1],verdict=verdict,reason=reason,evidence=refs,suggested_correction=fix))
